import { readFileSync, writeFileSync } from "node:fs";
const path = "data/city-pages.json";
const data = JSON.parse(readFileSync(path, "utf8"));
let added = 0, skipped = 0, fixed = 0;
for (const e of ENTRIES) {
  // dedupe the double Garden City entry defensively: second one updates first
  const existing = data.find((c) => c.state === e.state && c.slug === e.slug);
  if (existing) {
    // keep existing, do not overwrite approved content
    skipped++;
    continue;
  }
  data.push(e);
  added++;
}
// fix the duplicate Garden City slugs (garden-city + garden-city-mi-2): rename second properly
const dup = data.filter((c) => c.state === "mi" && c.city === "Garden City");
if (dup.length === 2 && dup[1].slug === "garden-city-mi-2") {
  // merge: keep first as the canonical page; remove second
  const idx = data.indexOf(dup[1]);
  data.splice(idx, 1);
  fixed++;
}
writeFileSync(path, JSON.stringify(data, null, 2));
console.log(`Batch 12: added ${added}, skipped ${skipped}, total ${data.length}`);
